async function readSpacingBank(){try{return await centralDirectoryRequest('/api/spacing-bank');}catch(error){if(!error.retryable||error.authRequired)throw error;await new Promise(resolve=>setTimeout(resolve,500));return centralDirectoryRequest('/api/spacing-bank');}}
let spacingBank=null,bankBusy=false,bankCache=null,bankPending=null;const bankResources=['metal','crystal','eonium'];
function bankContext(){return {player:state.centralPlayerId,generation:[state.centralResetGeneration??0,state.enrolledGeneration??0,state.resetGeneration??0].join(':'),snapshot:state};}
function sameBankContext(a,b){return !!a&&a.player===b.player&&a.generation===b.generation&&a.snapshot===b.snapshot;}
async function loadSpacingBank(force=false){const context=bankContext();if(!force&&bankCache&&sameBankContext(bankCache.context,context)&&Date.now()-bankCache.at<30000){spacingBank=bankCache.data;return spacingBank;}if(bankPending&&sameBankContext(bankPending.context,context))return bankPending.promise;const pending={context};pending.promise=readSpacingBank().then(data=>{if(sameBankContext(context,bankContext())){spacingBank=data;bankCache={context,data,at:Date.now()};}return data;}).finally(()=>{if(bankPending===pending)bankPending=null;});bankPending=pending;return pending.promise;}
function ensureSpacingBankMounted(){const root=document.getElementById('galaxyFundContent');if(!root||!state.centralPlayerId)return;let module=root.querySelector('#spacingBankModule');if(module&&!sameBankContext(module.bankContext,bankContext())){module.remove();module=null;spacingBank=null;}if(!module)void renderSpacingBank();}


function bankStatsHTML(b){return '<div class="alliance-kpis">'+bankResources.map(k=>'<div class="quick"><small>'+RES[k].label+' reserves</small><strong>'+nfmt(b.balances[k])+'</strong><span>Minimum '+nfmt(b.settings.minimum[k])+'</span></div>').join('')+'</div><p class="meta">Tax '+b.settings.tax+'% · Maximum exchange '+nfmt(b.settings.maxTrade)+' · Per-player tick limit '+nfmt(b.settings.tickLimit)+' · Total traded '+nfmt(b.volume)+'</p>';}

function bankExchangePanelHTML(from,b){const label=RES[from].label;return '<section class="bank-exchange-panel resource-transfer-row" data-bank-panel="'+from+'" aria-labelledby="bankTitle-'+from+'"><h3 id="bankTitle-'+from+'" class="resource-transfer-type"><i class="resource-transfer-icon" data-resource="'+from+'" aria-hidden="true"></i>'+esc(label)+'</h3><div class="resource-transfer-stock"><small>Available</small><b>'+nfmt(state.resources[from]||0)+'</b></div><div class="field"><label for="bankTo-'+from+'">Receive</label><select id="bankTo-'+from+'" data-bank-input="'+from+'">'+bankResources.filter(k=>k!==from).map(k=>'<option value="'+k+'">'+esc(RES[k].label)+'</option>').join('')+'</select></div><div class="field"><label for="bankAmount-'+from+'">Amount offered</label><input id="bankAmount-'+from+'" data-bank-input="'+from+'" type="number" min="1" step="1" max="'+b.settings.maxTrade+'" value="'+Math.min(1000,b.settings.maxTrade)+'"></div><p id="bankQuote-'+from+'" class="resource-transfer-result" aria-live="polite"></p><div class="resource-transfer-action"><button class="btn primary" data-bank-trade="'+from+'" aria-label="CONFIRM '+esc(label.toUpperCase())+' EXCHANGE">EXCHANGE</button><p id="bankMessage-'+from+'" class="bank-exchange-message" role="status"></p></div></section>';}
async function renderSpacingBank(force=false){const root=document.getElementById('galaxyFundContent'),context=bankContext();if(!root||!context.player)return;let module=root.querySelector('#spacingBankModule');if(module&&!sameBankContext(module.bankContext,context)){module.remove();module=null;}if(!module){module=document.createElement('section');module.id='spacingBankModule';module.className='panel';module.bankContext=context;module.hidden=(window.spaceportView||'fund')!=='bank';module.innerHTML='<div class="ph"><div class="pt">SPACING BANK COLLECTIVE</div></div><p role="status">Loading resource exchange…</p>';root.append(module);}const renderToken=module.bankRenderToken=(module.bankRenderToken||0)+1;const valid=()=>module.bankRenderToken===renderToken&&sameBankContext(context,bankContext())&&document.getElementById('galaxyFundContent')===root&&root.querySelector('#spacingBankModule')===module;const inputs=Object.fromEntries(bankResources.flatMap(from=>['bankTo-'+from,'bankAmount-'+from]).map(id=>[id,document.getElementById(id)?.value]));try{const b=await loadSpacingBank(force);if(!valid())return;if(module.contains(document.activeElement)&&['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;module.hidden=(window.spaceportView||'fund')!=='bank';module.innerHTML='<div class="ph"><div class="pt">SPACING BANK COLLECTIVE</div><span class="meta">UNIVERSAL RESOURCE EXCHANGE · ROUND '+b.generation+'</span></div><div class="settings-body"><p>Exchange with the common treasury. Reserves and fees are checked at settlement.</p>'+bankStatsHTML(b)+'<div class="bank-exchange-panels resource-transfer-list">'+bankResources.map(from=>bankExchangePanelHTML(from,b)).join('')+'</div><h4>Personal exchange receipts</h4>'+b.history.filter(t=>t.action==='trade').map(t=>'<p>Tick '+t.tick+' · '+nfmt(t.amount)+' '+esc(t.from)+' → '+nfmt(t.receive)+' '+esc(t.to)+' · Tax '+nfmt(t.fee)+' '+esc(t.to)+'</p>').join('')+'</div>';for(const [id,value]of Object.entries(inputs)){const input=document.getElementById(id);if(input&&value!==undefined)input.value=value;}updateBankQuote();}catch(e){if(!valid())return;module.innerHTML='<div class="ph"><div class="pt">SPACING BANK COLLECTIVE</div></div><p role="alert">'+esc(e.message||'Unable to load the bank.')+'</p>'+(e.authRequired?'<a class="btn" href="/login.html">SIGN IN AGAIN</a>':'')+'<button class="btn" data-bank-retry>RETRY BANK</button>';}}
function updateBankQuote(resource){if(!spacingBank)return;for(const from of resource?[resource]:bankResources){const to=document.getElementById('bankTo-'+from)?.value,amount=Number(document.getElementById('bankAmount-'+from)?.value),out=document.getElementById('bankQuote-'+from);if(!out)continue;if(!bankResources.includes(to)||to===from||!Number.isSafeInteger(amount)||amount<1||amount>spacingBank.settings.maxTrade){out.textContent='Enter a whole amount from 1 to '+nfmt(spacingBank.settings.maxTrade)+'.';continue;}const gross=Math.floor(amount*spacingBank.settings.values[from]/spacingBank.settings.values[to]),fee=Math.floor(gross*spacingBank.settings.tax/100);out.textContent='Receive '+nfmt(gross-fee)+' '+to+' · Fee '+nfmt(fee)+' '+to+' · Your '+from+' stock '+nfmt(state.resources[from]);}}
async function tradeSpacingBank(from){if(bankBusy||!spacingBank||!bankResources.includes(from))return;const context=bankContext(),b=spacingBank,to=document.getElementById('bankTo-'+from)?.value,amount=Number(document.getElementById('bankAmount-'+from)?.value),message=document.getElementById('bankMessage-'+from);if(!bankResources.includes(to)||from===to||!Number.isSafeInteger(amount)||amount<1||amount>b.settings.maxTrade){if(message)message.textContent='Choose another resource and a whole amount within the transaction limit.';return;}bankBusy=true;if(message)message.textContent='Settling exchange…';document.querySelectorAll('[data-bank-trade]').forEach(button=>button.disabled=true);try{if(typeof syncOwnedColony==='function')await syncOwnedColony(true);const fresh=await readSpacingBank();if(!sameBankContext(context,bankContext()))throw Error('Your planet changed. Reopen the bank before trading.');if(fresh.revision!==b.revision||JSON.stringify(fresh.settings)!==JSON.stringify(b.settings))throw Error('The quote changed. Review the updated bank and confirm again.');const transactionId=crypto.randomUUID(),result=await centralDirectoryRequest('/api/spacing-bank',{action:'trade',id:transactionId,generation:b.generation,revision:b.revision,from,to,amount});if(!sameBankContext(context,bankContext()))return;recordOrderConfirmation('universal-bank-trade',{id:transactionId,...result.trade});await refreshSharedPlanets();if(!sameBankContext(context,bankContext()))return;update();await renderSpacingBank(true);const settled=document.getElementById('bankMessage-'+from);if(settled)settled.textContent='Exchange settled.';}catch(e){await renderSpacingBank(true);const failed=document.getElementById('bankMessage-'+from);if(failed)failed.textContent=e.message;}finally{bankBusy=false;document.querySelectorAll('[data-bank-trade]').forEach(button=>button.disabled=false);}}
async function renderSpacingBankAdmin(){const root=document.getElementById('spacingBankAdmin');if(!root)return;try{const b=await loadSpacingBank(true);if(!b.canConfigure){root.textContent='Staff access required.';return;}root.innerHTML='<section class="panel"><div class="ph"><div class="pt">SPACING BANK COLLECTIVE · TREASURY CONTROL</div><span class="meta">CHANGES ARE LOGGED</span></div><div class="settings-body">'+bankStatsHTML(b)+'<p>Starting reserves apply on the next round. Exchange limits, values, minimums and tax apply after saving. Tax is retained as reduced output, not minted separately.</p><div class="admin-form">'+bankResources.map(k=>'<div class="field"><label>'+RES[k].label+' round start</label><input type="number" min="0" id="bankStarting-'+k+'" value="'+b.settings.starting[k]+'" '+(b.canSetStarting?'':'disabled')+'></div><div class="field"><label>'+RES[k].label+' minimum reserve</label><input type="number" min="0" id="bankMinimum-'+k+'" value="'+b.settings.minimum[k]+'"></div><div class="field"><label>'+RES[k].label+' exchange value</label><input type="number" min="0.1" max="100" step="0.1" id="bankValue-'+k+'" value="'+b.settings.values[k]+'"></div>').join('')+'<div class="field"><label>Exchange tax %</label><input type="number" min="0" max="25" id="bankTax" value="'+b.settings.tax+'"></div><div class="field"><label>Maximum transaction</label><input type="number" min="1" id="bankMax" value="'+b.settings.maxTrade+'"></div><div class="field"><label>Per-player, per-tick allowance</label><input type="number" min="1" id="bankTick" value="'+b.settings.tickLimit+'"></div></div><button class="btn primary" data-bank-configure>SAVE BANK POLICY</button><p id="bankAdminMessage"></p></div></section>';}catch(e){root.textContent=e.message;}}
async function configureSpacingBank(){const settings={starting:{},minimum:{},values:{},tax:Number(document.getElementById('bankTax').value),maxTrade:Number(document.getElementById('bankMax').value),tickLimit:Number(document.getElementById('bankTick').value)};for(const k of bankResources){settings.starting[k]=Number(document.getElementById('bankStarting-'+k).value);settings.minimum[k]=Number(document.getElementById('bankMinimum-'+k).value);settings.values[k]=Number(document.getElementById('bankValue-'+k).value);}try{await centralDirectoryRequest('/api/spacing-bank',{action:'configure',settings});await renderSpacingBankAdmin();document.getElementById('bankAdminMessage').textContent='Policy saved. Starting reserves apply next round.';}catch(e){document.getElementById('bankAdminMessage').textContent=e.message;}}
document.addEventListener('input',e=>{if(e.target.dataset.bankInput)updateBankQuote(e.target.dataset.bankInput);});document.addEventListener('click',e=>{if(e.target.closest('[data-bank-retry]'))void renderSpacingBank(true);const trade=e.target.closest('[data-bank-trade]');if(trade)tradeSpacingBank(trade.dataset.bankTrade);if(e.target.closest('[data-bank-configure]'))configureSpacingBank();if(e.target.closest('[data-page="galaxyFund"]'))setTimeout(renderSpacingBank,100);});setTimeout(renderSpacingBank,3000);setInterval(()=>{if(document.getElementById('page-galaxyFund')?.classList.contains('active')&&!document.querySelector('#spacingBankModule input:focus,#spacingBankModule select:focus'))renderSpacingBank();},30000);
